+import static com.netflix.titus.master.mesos.kubeapiserver.KubeConstants.PENDING;
+
+/**
+ * Responsible for deleting Kubernetes pod objects when they no longer exist in agent management. This will eventually be moved
+ * to a new component.
+ */
+
+@Singleton
+public class PodGcController {
+    private static final Logger logger = LoggerFactory.getLogger(PodGcController.class);
+    private static final String METRIC_ROOT = MetricConstants.METRIC_KUBERNETES_CONTROLLER + "podGcController.";
+
+    private final KubeControllerConfiguration configuration;
+    private final KubeApiFacade kubeApiFacade;
+    private final LocalScheduler scheduler;
+
+    private final Clock clock;
+    private final Gauge podsOnUnknownNodes;
+    private final Gauge podsPastDeletionTimestampToGcGauge;
+    private final Gauge pendingPodsWithDeletionTimestampToGcGauge;
+
+    @Inject
+    public PodGcController(KubeControllerConfiguration configuration,
+                           TitusRuntime titusRuntime,
+                           KubeApiFacade kubeApiFacade,
+                           LocalScheduler scheduler) {
+        this.configuration = configuration;
+        this.kubeApiFacade = kubeApiFacade;
+        this.scheduler = scheduler;
+
+        this.clock = titusRuntime.getClock();
+
+        Registry registry = titusRuntime.getRegistry();
+        podsOnUnknownNodes = registry.gauge(METRIC_ROOT + "podsOnUnknownNodes");
+        podsPastDeletionTimestampToGcGauge = registry.gauge(METRIC_ROOT + "podsPastDeletionTimestampToGc");
+        pendingPodsWithDeletionTimestampToGcGauge = registry.gauge(METRIC_ROOT + "pendingPodsWithDeletionTimestampToGc");
+    }
+
+    @Activator
+    public void enterActiveMode() {
+        ScheduleDescriptor reconcileSchedulerDescriptor = ScheduleDescriptor.newBuilder()
+                .withName("podGcController")
+                .withDescription("Clean up pods that need to be garbage collected")
+                .withInitialDelay(Duration.ofMillis(configuration.getPodGcControllerInitialDelayMs()))
+                .withInterval(Duration.ofMillis(configuration.getPodGcControllerIntervalMs()))
+                .withTimeout(Duration.ofMillis(configuration.getPodGcControllerTimeoutMs()))
+                .build();
+        scheduler.schedule(reconcileSchedulerDescriptor, e -> gcPods(), ExecutorsExt.namedSingleThreadExecutor("pod-gc-controller"));
+    }
+
+    void gcPods() {
+        if (!kubeApiFacade.getNodeInformer().hasSynced()) {
+            logger.info("Node informer has not synced");
+            return;
+        }
+
+        if (!kubeApiFacade.getPodInformer().hasSynced()) {
+            logger.info("Pod informer has not synced");
+            return;
+        }
+
+        if (!configuration.isPodGcControllerEnabled()) {
+            logger.info("Pod GC is disabled");
+            return;
+        }
+
+        List<V1Node> nodes = kubeApiFacade.getNodeInformer().getIndexer().list();
+        List<V1Pod> pods = kubeApiFacade.getPodInformer().getIndexer().list();
+
+        gcPodsOnUnknownNode(nodes, pods);
+        gcPodsPastDeletionTimestamp(pods);
+        gcPendingPodsWithDeletionTimestamp(pods);
+    }
+
+    /**
+     * GC pods on unknown nodes
+     */
+    private void gcPodsOnUnknownNode(List<V1Node> nodes, List<V1Pod> pods) {
+        Set<String> knownNodeNames = nodes.stream().map(n -> KubeUtil.getMetadataName(n.getMetadata())).collect(Collectors.toSet());
+        List<V1Pod> podsOnUnknownNodes = pods.stream()
+                .filter(p -> isPodOnUnknownNode(p, knownNodeNames))
+                .collect(Collectors.toList());
+
+        logger.info("Attempting to GC {} pods: {} on unknown nodes", podsOnUnknownNodes.size(),
+                podsOnUnknownNodes);
+        this.podsOnUnknownNodes.set(podsOnUnknownNodes.size());
+        for (V1Pod pod : podsOnUnknownNodes) {
+            gcPod(pod);
+        }
+        logger.info("Finished pod GC on unknown nodes");
+    }
+
+    @VisibleForTesting
+    boolean isPodOnUnknownNode(V1Pod pod, Set<String> knownNodeNames) {
+        if (pod == null || pod.getSpec() == null) {
+            return false;
+        }
+
+        String nodeName = pod.getSpec().getNodeName();
+        return StringExt.isNotEmpty(nodeName) && !knownNodeNames.contains(nodeName);
+    }
+
+    /**
+     * GC pods past deletion timestamp timeout.
+     */
+    private void gcPodsPastDeletionTimestamp(List<V1Pod> pods) {
+        List<V1Pod> podsPastDeletionTimestampToGc = pods.stream()
+                .filter(this::isPodPastDeletionTimestamp)
+                .collect(Collectors.toList());
+
+        logger.info("Attempting to GC {} pods: {} past deletion timestamp", podsPastDeletionTimestampToGc.size(),
+                podsPastDeletionTimestampToGc);
+        podsPastDeletionTimestampToGcGauge.set(podsPastDeletionTimestampToGc.size());
+        for (V1Pod pod : podsPastDeletionTimestampToGc) {
+            gcPod(pod);
+        }
+        logger.info("Finished pods past deletion timestamp GC");
+    }
+
+    @VisibleForTesting
+    boolean isPodPastDeletionTimestamp(V1Pod pod) {
+        V1PodSpec spec = pod.getSpec();
+        V1ObjectMeta metadata = pod.getMetadata();
+        if (spec == null || metadata == null) {
+            return false;
+        }
+
+        Long terminationGracePeriodSeconds = spec.getTerminationGracePeriodSeconds();
+        DateTime deletionTimestamp = metadata.getDeletionTimestamp();
+        if (terminationGracePeriodSeconds == null || deletionTimestamp == null) {
+            return false;
+        }
+
+        long terminationGracePeriodMs = terminationGracePeriodSeconds * 1000L;
+        return clock.isPast(deletionTimestamp.getMillis() + terminationGracePeriodMs
+                + configuration.getPodsPastTerminationGracePeriodMs());
+    }
+
+    /**
+     * GC pods in Pending phase with a deletion timestamp.
+     */
+    private void gcPendingPodsWithDeletionTimestamp(List<V1Pod> pods) {
+        List<V1Pod> pendingPodsWithDeletionTimestampToGc = pods.stream()
+                .filter(this::isPodInPendingPhaseWithDeletionTimestamp)
+                .collect(Collectors.toList());
+
+        logger.info("Attempting to GC {} pending pods: {} with deletion timestamp", pendingPodsWithDeletionTimestampToGc.size(),
+                pendingPodsWithDeletionTimestampToGc);
+        pendingPodsWithDeletionTimestampToGcGauge.set(pendingPodsWithDeletionTimestampToGc.size());
+        for (V1Pod pod : pendingPodsWithDeletionTimestampToGc) {
+            gcPod(pod);
+        }
+        logger.info("Finished pending pods with deletion timestamp GC");
+    }
+
+    @VisibleForTesting
+    boolean isPodInPendingPhaseWithDeletionTimestamp(V1Pod pod) {
+        if (pod == null || pod.getMetadata() == null || pod.getStatus() == null) {
+            return false;
+        }
+        DateTime deletionTimestamp = pod.getMetadata().getDeletionTimestamp();
+        return deletionTimestamp != null && PENDING.equalsIgnoreCase(pod.getStatus().getPhase());
+    }
